// HubSpot Property Definitions
// One item per custom contact property in the "Lead Router" group.
// The next node creates each one; a 409 response means it already exists, which is fine.

const group = 'lead_router';
const text = (name, label, description) => ({ name, label, description, groupName: group, type: 'string', fieldType: 'text' });
const area = (name, label, description) => ({ name, label, description, groupName: group, type: 'string', fieldType: 'textarea' });

const properties = [
  { name: 'lr_lead_score', label: 'Lead Score (Router)', description: 'Score from the lead router scoring rules', groupName: group, type: 'number', fieldType: 'number' },
  {
    name: 'lr_priority', label: 'Lead Priority (Router)', description: 'Hot, Warm or Cold', groupName: group,
    type: 'enumeration', fieldType: 'select',
    options: [
      { label: 'Hot', value: 'Hot', displayOrder: 0 },
      { label: 'Warm', value: 'Warm', displayOrder: 1 },
      { label: 'Cold', value: 'Cold', displayOrder: 2 },
    ],
  },
  text('lr_assigned_rep', 'Assigned Rep (Router)', 'Rep the router assigned this contact to'),
  text('lr_assigned_rep_id', 'Assigned Rep ID (Router)', 'rep_id from the reps tab of the config sheet'),
  area('lr_routing_reason', 'Routing Reason', 'Why the router sent the lead to this rep'),
  text('lr_source', 'Lead Source (Router)', 'Web form, Webhook or Google Sheet'),
  text('lr_service_interest', 'Service Interest', 'Service the lead asked about'),
  text('lr_company_size', 'Company Size Band', 'Employee band, for example 51-200'),
  text('lr_budget', 'Budget Band', 'Budget band, for example $15k-$50k'),
  text('lr_timeline', 'Buying Timeline', 'ASAP, 1-3 months, 3-6 months or Just researching'),
  area('lr_last_message', 'Last Message', 'Most recent message the lead sent'),
];

return properties.map((p) => ({ json: p }));

// Setup Summary
// Collects the result of every check above into one readable checklist.
// Each check node is set to "continue on error", so a failure shows up here instead of stopping the run.

const cfg = $('Config').first().json.config;
const results = [];
const errorOf = (items) => {
  const bad = items.find((i) => i.json && i.json.error);
  if (!bad) return '';
  const e = bad.json.error;
  return typeof e === 'string' ? e : (e.message || JSON.stringify(e)).slice(0, 300);
};
const safeAll = (name) => { try { return $(name).all(); } catch (e) { return []; } };

// 1. Postgres
const db = safeAll('Create Database Tables');
results.push({ check: 'Postgres: lead_router tables', ok: db.length > 0 && !errorOf(db), detail: errorOf(db) || 'Tables and views are in place' });

// 2. HubSpot access and Hub ID
const access = safeAll('Check HubSpot Access');
const accessOk = access.length > 0 && !errorOf(access) && Array.isArray(access[0].json.results);
results.push({
  check: 'HubSpot: key works and can read contacts',
  ok: accessOk,
  detail: accessOk ? 'Contacts API reachable with this key' : (errorOf(access) || 'Unexpected response. Check the key and its crm.objects.contacts scopes.'),
});
const account = safeAll('Get HubSpot Account');
const portalId = account[0]?.json?.portalId;
results.push({
  check: 'HubSpot: Hub ID',
  ok: true,
  detail: portalId
    ? `Hub ID ${portalId}. Put this number in hubspot_portal_id in the Config node of "02 - Process Lead".`
    : 'Not returned for this key. Copy it from your HubSpot URL instead (the number after app.hubspot.com/contacts/).',
});

// 3. HubSpot properties
const props = safeAll('Create HubSpot Properties');
const statusOf = (i) => Number(i.json.statusCode || 0);
const created = props.filter((i) => statusOf(i) === 201).length;
const existing = props.filter((i) => statusOf(i) === 409).length;
const failed = props.filter((i) => ![201, 409].includes(statusOf(i)));
const failMsgs = [...new Set(failed.map((i) => `${statusOf(i) || 'error'} ${String(i.json.body?.message || i.json.error?.message || i.json.error || '').slice(0, 160)}`))];
results.push({
  check: 'HubSpot: Lead Router properties',
  ok: props.length > 0 && failed.length === 0,
  detail: failed.length
    ? `${failed.length} of ${props.length} failed: ${failMsgs.join(' | ')}. A 403 usually means the key is missing the crm.schemas.contacts.write scope.`
    : `${created} created, ${existing} already existed`,
});

// 4. Google Sheet
const reps = safeAll('Check Config Sheet');
const repRows = reps.filter((i) => i.json && i.json.rep_id);
results.push({
  check: 'Google Sheets: config sheet readable',
  ok: repRows.length > 0,
  detail: repRows.length ? `${repRows.length} reps found in the reps tab` : (errorOf(reps) || `No reps found. Check sheet_id (${cfg.sheet_id}) and that the sheet is shared with the service account.`),
});

// 4b. One-call read of all three config tabs (what 02 - Process Lead uses)
const tabsRead = safeAll('Check Config Read (HTTP)');
const tabsRes = tabsRead[0]?.json || {};
const tabsStatus = Number(tabsRes.statusCode || 0);
const tabRanges = tabsRes.body?.valueRanges || [];
const tabsOk = tabsStatus === 200 && tabRanges.length === 3 && tabRanges.every((r) => (r.values || []).length > 1);
const tabsMsg = String(tabsRes.body?.error?.message || errorOf(tabsRead) || '').slice(0, 200);
results.push({
  check: 'Google Sheets: one-call read of the three config tabs',
  ok: tabsOk,
  detail: tabsOk
    ? 'scoring_rules, territories and reps read in a single request'
    : `HTTP ${tabsStatus || 'error'}${tabsMsg ? `: ${tabsMsg}` : ''}. In the "Lead Router - Google Service Account" credential, turn on "Set up for use in HTTP Request node" and set Scope(s) to https://www.googleapis.com/auth/spreadsheets.readonly`,
});

// 5. Slack
const slack = safeAll('Check Slack');
results.push({
  check: 'Slack: can post to the alerts channel',
  ok: slack.length > 0 && !errorOf(slack) && slack[0].json.ok !== false,
  detail: errorOf(slack) || `Test message posted to ${cfg.slack_alerts_channel}`,
});

const allOk = results.every((r) => r.ok);
return [
  { json: { summary: allOk ? 'ALL CHECKS PASSED. You are ready to publish "01 - Lead Intake".' : `${results.filter((r) => !r.ok).length} check(s) failed. Fix them and run this workflow again.` } },
  ...results.map((r) => ({ json: { status: r.ok ? 'PASS' : 'FAIL', ...r } })),
];
